mapper.select:
 SELECT
		interview_available_dtm FROM TBL_PROJECT_INTERVIEW_TIME_SLOT_S WHERE interview_sq =
		#{interviewSq}

SELECT a.project_application_sq AS applicationSq, p.project_sq AS projectSq, p.project_ttl AS projectTitle, c.company_nm AS companyTitle, a.project_application_created_at_dtm AS appliedDt, a.selected_interview_dtm AS interviewDt, r.resume_sq AS resumeSq, r.resume_ttl AS resumeTitle, p.project_candidate_cnt AS applicantCnt, a.read_application_dtm AS readApplicationDt, cc.common_code_nm AS applicantType, CASE WHEN p.project_recruit_end_dt < CURDATE() THEN TRUE ELSE FALSE END AS isRecruitEnded FROM TBL_RESUME_M r JOIN TBL_PROJECT_APPLICATION_H a ON r.resume_sq = a.resume_sq JOIN TBL_PROJECT_M p ON a.project_sq = p.project_sq JOIN TBL_COMPANY_S c ON p.company_sq = c.company_sq JOIN TBL_COMMON_CODE_C cc ON a.project_application_status_cd = cc.common_code_sq WHERE r.user_sq = #{userSq}
AND p.project_ttl LIKE CONCAT('%', #{keyword}, '%') AND c.company_nm LIKE CONCAT('%', #{keyword}, '%')
AND (p.project_ttl LIKE CONCAT('%', #{keyword}, '%') OR c.company_nm LIKE CONCAT('%', #{keyword}, '%'))
AND a.read_application_dtm IS NOT NULL AND a.read_application_dtm IS NULL
ORDER BY a.project_application_created_at_dtm DESC LIMIT #{size} OFFSET #{offset}

 SELECT CASE
		project_application_member_type_cd WHEN 301 THEN '개인' WHEN 302 THEN '기업' ELSE 'UNKNOWN' END
		FROM TBL_PROJECT_APPLICATION_H WHERE project_application_sq = #{applicationSq}

