 UPDATE TBL_PROJECT_APPLICATION_H SET
		project_application_status_cd = #{newStatusCd} WHERE project_application_sq =
		#{applicationSq}

 UPDATE TBL_PROJECT_APPLICATION_H SET
		selected_interview_dtm = #{interviewTime}, project_application_status_cd = 805 WHERE
		project_application_sq = #{applicationSq}

mapper.select:
SELECT DISTINCT c.company_nm FROM TBL_PROJECT_APPLICATION_H a JOIN TBL_COMPANY_S c ON a.company_sq = c.company_sq JOIN TBL_RESUME_M r ON a.resume_sq = r.resume_sq JOIN TBL_COMMON_CODE_C cc ON a.project_application_status_cd = cc.common_code_sq WHERE a.project_sq = #{projectSq}
AND cc.common_code_nm = '합격' AND cc.common_code_nm = '지원중' AND cc.common_code_nm = '인터뷰확정' AND cc.common_code_nm = '인터뷰요청중' AND cc.common_code_nm IN ('불합격', '지원취소')
AND LOWER(r.resume_nm) LIKE CONCAT('%', LOWER(#{keyword}), '%') AND EXISTS ( SELECT 1 FROM TBL_RESUME_SKILL_TAG_S st JOIN TBL_SKILL_TAG_C s ON st.skill_tag_sq = s.skill_tag_sq WHERE st.resume_sq = r.resume_sq AND LOWER(s.skill_tag_nm) LIKE CONCAT('%', LOWER(#{keyword}), '%') ) AND ( LOWER(r.resume_nm) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR EXISTS ( SELECT 1 FROM TBL_RESUME_SKILL_TAG_S st JOIN TBL_SKILL_TAG_C s ON st.skill_tag_sq = s.skill_tag_sq WHERE st.resume_sq = r.resume_sq AND LOWER(s.skill_tag_nm) LIKE CONCAT('%', LOWER(#{keyword}), '%') ) )
ORDER BY c.company_nm LIMIT #{size} OFFSET #{offset}

SELECT COUNT(DISTINCT a.company_sq) FROM TBL_PROJECT_APPLICATION_H a JOIN TBL_COMPANY_S c ON a.company_sq = c.company_sq JOIN TBL_RESUME_M r ON a.resume_sq = r.resume_sq JOIN TBL_COMMON_CODE_C cc ON a.project_application_status_cd = cc.common_code_sq WHERE a.project_sq = #{projectSq}
AND cc.common_code_nm = '합격' AND cc.common_code_nm = '지원중' AND cc.common_code_nm = '인터뷰확정' AND cc.common_code_nm = '인터뷰요청중' AND cc.common_code_nm IN ('불합격', '지원취소')
AND LOWER(r.resume_nm) LIKE CONCAT('%', LOWER(#{keyword}), '%') AND EXISTS ( SELECT 1 FROM TBL_RESUME_SKILL_TAG_S st JOIN TBL_SKILL_TAG_C s ON st.skill_tag_sq = s.skill_tag_sq WHERE st.resume_sq = r.resume_sq AND LOWER(s.skill_tag_nm) LIKE CONCAT('%', LOWER(#{keyword}), '%') ) AND ( LOWER(r.resume_nm) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR EXISTS ( SELECT 1 FROM TBL_RESUME_SKILL_TAG_S st JOIN TBL_SKILL_TAG_C s ON st.skill_tag_sq = s.skill_tag_sq WHERE st.resume_sq = r.resume_sq AND LOWER(s.skill_tag_nm) LIKE CONCAT('%', LOWER(#{keyword}), '%') ) )

SELECT a.project_application_sq AS applicationSq, p.project_sq AS projectSq, p.project_ttl AS projectTitle, (SELECT c.company_nm FROM TBL_COMPANY_S c WHERE c.company_sq = p.company_sq) AS companyTitle, p.project_candidate_cnt AS applicantCnt, u.user_nm AS applicantName, r.resume_sq AS resumeSq, r.resume_ttl AS resumeTitle, a.project_application_created_at_dtm AS appliedDt, a.selected_interview_dtm AS interviewDt, a.read_application_dtm AS readApplicationDt, cc.common_code_nm AS applicantType, CASE WHEN p.project_recruit_end_dt < CURDATE() THEN TRUE ELSE FALSE END AS isRecruitEnded FROM TBL_PROJECT_APPLICATION_H a JOIN TBL_PROJECT_M p ON a.project_sq = p.project_sq JOIN TBL_RESUME_M r ON a.resume_sq = r.resume_sq JOIN TBL_USER_M u ON r.user_sq = u.user_sq JOIN TBL_COMMON_CODE_C cc ON a.project_application_status_cd = cc.common_code_sq WHERE a.company_sq = #{companySq}
AND p.project_ttl LIKE CONCAT('%', #{keyword}, '%') AND u.user_nm LIKE CONCAT('%', #{keyword}, '%') AND (p.project_ttl LIKE CONCAT('%', #{keyword}, '%') OR u.user_nm LIKE CONCAT('%', #{keyword}, '%'))
AND a.read_application_dtm IS NOT NULL AND a.read_application_dtm IS NULL
ORDER BY a.project_application_created_at_dtm DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM TBL_PROJECT_APPLICATION_H a JOIN TBL_PROJECT_M p ON a.project_sq = p.project_sq JOIN TBL_RESUME_M r ON a.resume_sq = r.resume_sq JOIN TBL_USER_M u ON r.user_sq = u.user_sq WHERE a.company_sq = #{companySq}
AND p.project_ttl LIKE CONCAT('%', #{keyword}, '%') AND u.user_nm LIKE CONCAT('%', #{keyword}, '%') AND (p.project_ttl LIKE CONCAT('%', #{keyword}, '%') OR u.user_nm LIKE CONCAT('%', #{keyword}, '%'))
AND a.read_application_dtm IS NOT NULL AND a.read_application_dtm IS NULL
